package ru.ryadom.calendar;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.CalendarContract;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class CalendarWriteTest {
 Context c;Instrumentation ins;List<Long> calendars=new ArrayList<>();long from,to;
 @Before public void setup()throws Exception{assertTrue(Build.HARDWARE.equals("ranchu")||Build.HARDWARE.equals("goldfish"));ins=InstrumentationRegistry.getInstrumentation();c=ins.getTargetContext();for(String permission:new String[]{"READ_CALENDAR","WRITE_CALENDAR"})try(ParcelFileDescriptor pipe=ins.getUiAutomation().executeShellCommand("pm grant "+c.getPackageName()+" android.permission."+permission)){try(java.io.FileInputStream in=new java.io.FileInputStream(pipe.getFileDescriptor())){while(in.read()!=-1){}}}from=System.currentTimeMillis()-86400000L;to=from+7*86400000L;Store.edit(c,d->{for(String key:new String[]{"mirrorLinks","calendarRoles","hidden","statuses","seen"})d.put(key,new JSONObject());d.put("accounts",new JSONArray());d.put("events",new JSONArray());d.put("systemExport",false);});}
 long calendar(String name)throws Exception{ContentValues v=new ContentValues();v.put("account_name",DeviceWrites.OWNER);v.put("account_type",CalendarContract.ACCOUNT_TYPE_LOCAL);v.put("name","test-"+UUID.randomUUID());v.put("calendar_displayName",name);v.put("calendar_color",0xff276a4f);v.put("calendar_access_level",700);v.put("ownerAccount",DeviceWrites.OWNER);v.put("visible",1);v.put("sync_events",1);v.put("allowedReminders","1");v.put("maxReminders",5);long id=ContentUris.parseId(c.getContentResolver().insert(DeviceWrites.adapter(CalendarContract.Calendars.CONTENT_URI),v));calendars.add(id);return id;}
 JSONObject account(String id,long calendar)throws Exception{return new JSONObject().put("id",id).put("type","device").put("calendarIds",new JSONArray().put(""+calendar)).put("active",true);}
 Event event(){Event e=new Event();e.title="Пример встречи";e.description="Тестовое описание";e.location="Тестовая комната";e.start=System.currentTimeMillis()+86400000L;e.end=e.start+3600000L;e.reminderMinutes=37;return e;}
 void snapshot()throws Exception{JSONObject data=Store.read(c);JSONArray events=new JSONArray();JSONObject statuses=new JSONObject();for(JSONObject a:Mirror.accounts(data).values()){Providers.Result result=Providers.load(c,a,from,to);for(Event e:result.events)events.put(e.json());JSONObject cals=new JSONObject();for(Map.Entry<String,String> cal:result.calendars.entrySet())cals.put(cal.getKey(),cal.getValue());statuses.put(a.getString("id"),new JSONObject().put("success",System.currentTimeMillis()).put("rangeStart",from).put("rangeEnd",to).put("calendars",cals));}Store.edit(c,d->d.put("events",events).put("statuses",statuses));}
 int count(long calendar){try(Cursor rows=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"_id"},"calendar_id=? AND deleted=0",new String[]{""+calendar},null)){assertNotNull(rows);return rows.getCount();}}
 Event first(JSONObject a)throws Exception{return Providers.load(c,a,from,to).events.get(0);}
 @After public void clean(){for(long id:calendars)c.getContentResolver().delete(DeviceWrites.adapter(ContentUris.withAppendedId(CalendarContract.Calendars.CONTENT_URI,id)),null,null);Store.edit(c,d->{d.put("accounts",new JSONArray()).put("events",new JSONArray()).put("mirrorLinks",new JSONObject()).put("calendarRoles",new JSONObject()).put("systemExport",false);});}
 @Test public void writesCopiesPrivacyAndConfirmedDeletion()throws Exception{
  long source=calendar("Сателлит"),target=calendar("Основной"),second=calendar("Второй основной");JSONObject a=account("source",source),b=account("target",target),b2=account("second",second);Store.edit(c,d->d.put("accounts",new JSONArray().put(a).put(b).put(b2)).put("calendarRoles",new JSONObject().put("source|"+source,new JSONObject().put("role","satellite"))));
  Event original=event();original.source="source";original.calendar=""+source;original=EventWrites.save(c,a,""+source,null,original,"edit-fixture");assertEquals(37,first(a).reminderMinutes);EventWrites.save(c,a,""+source,null,original,"edit-fixture");assertEquals(1,count(source));snapshot();final boolean[] lost={false};Mirror.Writer uncertain=new Mirror.Writer(){public Event save(Context ctx,JSONObject acc,String cal,Event before,Event desired,String token)throws Exception{Event saved=Mirror.LIVE.save(ctx,acc,cal,before,desired,token);if(!lost[0]){lost[0]=true;throw new java.io.IOException("Simulated lost acknowledgement");}return saved;}public void delete(Context ctx,JSONObject acc,Event e)throws Exception{Mirror.LIVE.delete(ctx,acc,e);}};Mirror.run(c,Providers::deleted,uncertain);assertEquals(1,count(target));assertEquals(1,count(second));snapshot();Mirror.run(c,Providers::deleted);assertEquals(1,count(target));assertEquals(1,count(second));Event copy=first(b);assertEquals("Занят",copy.title);assertEquals("",copy.description);assertEquals("",copy.location);assertEquals(-1,copy.reminderMinutes);assertTrue(copy.copyToken.startsWith("copy-"));snapshot();Mirror.run(c,Providers::deleted);assertEquals(1,count(target));assertEquals(1,Sync.visible(Store.read(c),false).size());
  Store.edit(c,d->Store.object(d,"calendarRoles").getJSONObject("source|"+source).put("anonymous",false));Mirror.run(c,Providers::deleted);assertEquals("Пример встречи",first(b).title);assertEquals("Тестовое описание",first(b).description);assertEquals(-1,first(b).reminderMinutes);
  Event changed=Event.from(original.json());changed.start+=7200000;changed.end+=7200000;changed.reminderMinutes=-1;original=EventWrites.save(c,a,""+source,original,changed,"edit-fixture");snapshot();Mirror.run(c,Providers::deleted);assertEquals(changed.start,first(b).start);assertEquals(1,count(target));assertEquals(-1,first(a).reminderMinutes);
  Store.edit(c,d->Store.object(d,"calendarRoles").getJSONObject("source|"+source).put("anonymous",true));Mirror.run(c,Providers::deleted);assertEquals("Занят",first(b).title);assertEquals("",first(b).description);
  // A failed source read or a missing snapshot must not erase existing copies.
  Store.edit(c,d->Store.object(d,"statuses").getJSONObject("source").put("error","offline"));Mirror.run(c,(ctx,acc,e)->true);assertEquals(1,count(target));snapshot();Store.edit(c,d->d.put("events",new JSONArray()));Mirror.run(c,(ctx,acc,e)->false);assertEquals(1,count(target));
  EventWrites.delete(c,a,original);snapshot();Mirror.run(c,Providers::deleted);assertEquals(0,count(target));assertEquals(0,count(second));assertEquals(0,Store.object(Store.read(c),"mirrorLinks").length());
 }
 @Test public void exportUpsertsWithoutReimport()throws Exception{
  Event e=event();e.id="export-fixture";e.stableId=e.id;e.source="remote";e.calendar="main";JSONObject a=new JSONObject().put("id","remote").put("type","ews").put("active",false);Store.edit(c,d->d.put("accounts",new JSONArray().put(a)).put("events",new JSONArray().put(e.json())).put("systemExport",true));DeviceWrites.publish(c,Store.read(c));long cal=DeviceWrites.exportCalendar(c,false);calendars.add(cal);assertEquals(1,count(cal));DeviceWrites.publish(c,Store.read(c));assertEquals(1,count(cal));assertTrue(DeviceWrites.exported(c,""+cal));assertEquals(0,Providers.load(c,account("export",cal),from,to).events.size());e.title="Изменённая встреча";Store.edit(c,d->d.put("events",new JSONArray().put(e.json())));DeviceWrites.publish(c,Store.read(c));assertEquals(1,count(cal));try(Cursor row=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"title","hasAlarm"},"calendar_id=?",new String[]{""+cal},null)){assertTrue(row.moveToFirst());assertEquals(e.title,row.getString(0));assertEquals(0,row.getInt(1));}Store.edit(c,d->d.put("systemExport",false));DeviceWrites.publish(c,Store.read(c));assertEquals(0,count(cal));
 }

 @Test public void editorSavesCustomReminderAndReopens()throws Exception{
  long cal=calendar("Личный тестовый");JSONObject account=account("editor",cal);Store.edit(c,d->d.put("accounts",new JSONArray().put(account)));snapshot();MainActivity a=(MainActivity)ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ins.waitForIdleSync();for(int i=0;i<30&&Sync.busy.get();i++)Thread.sleep(100);EventEditor[] editor={null};try{ins.runOnMainSync(()->{a.handler.removeCallbacks(a.ticking);editor[0]=new EventEditor(a,null);editor[0].show();editor[0].title.setText("Планирование");editor[0].minutes.setText("42");editor[0].location.setText("Тестовая комната");});new UiTest().screenshot(ins,"editor-custom-reminder");ins.runOnMainSync(()->editor[0].save());for(int i=0;i<50&&count(cal)==0;i++)Thread.sleep(100);assertEquals(1,count(cal));assertEquals(42,first(account).reminderMinutes);ins.waitForIdleSync();for(int i=0;i<30&&Sync.busy.get();i++)Thread.sleep(100);Event saved=first(account);ins.runOnMainSync(()->{editor[0]=new EventEditor(a,saved);editor[0].show();assertEquals("42",editor[0].minutes.getText().toString());editor[0].none.setChecked(true);editor[0].save();});for(int i=0;i<50&&first(account).reminderMinutes!=-1;i++)Thread.sleep(100);assertEquals(-1,first(account).reminderMinutes);}finally{ins.runOnMainSync(()->{if(editor[0]!=null&&editor[0].dialog!=null)editor[0].dialog.dismiss();a.finish();});}
 }
}
